package com.botw;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("botw")
public interface BotwConfig extends Config
{
	@ConfigItem(
		keyName = "screenshotDrops",
		name = "Screenshot scoring drops",
		description = "Saves a picture under .runelite/botw whenever a drop scores you points.",
		position = 0
	)
	default boolean screenshotDrops()
	{
		return true;
	}

	@ConfigItem(
		keyName = "shareScreenshots",
		name = "Send screenshots to the challenge creator",
		description =
			"Sends a small copy of each scoring drop's screenshot to whoever runs the challenge, "
				+ "so they can verify it. Only they can see it. Turn this off to keep every screenshot "
				+ "on your own machine.",
		position = 1
	)
	default boolean shareScreenshots()
	{
		return true;
	}

	@ConfigItem(
		keyName = "discordWebhookUrl",
		name = "Discord leaderboard webhook",
		description = "Creators only: paste a Discord channel webhook URL, then open your challenge and "
			+ "select Post to Discord. Keep this URL private.",
		position = 2,
		secret = true
	)
	default String discordWebhookUrl()
	{
		return "";
	}

	@ConfigItem(
		keyName = "serverUrl",
		name = "Server address",
		description = "Where challenges and leaderboards live. Leave this alone unless your clan runs its own.",
		position = 3
	)
	default String serverUrl()
	{
		return "https://botw.marcushill3313.workers.dev";
	}
}

package com.botw;

import java.io.File;
import net.runelite.client.RuneLite;

/**
 * Every file this plugin writes, and the one place that decides where they go.
 * <p>
 * All of it lives under a folder of this plugin's own inside {@code .runelite}, which is what the
 * plugin hub requires: a plugin may write within its own subdirectory there and nowhere else. An
 * earlier version put screenshots in {@code .runelite/screenshots}, which is the client's folder
 * rather than this plugin's, and shared with everything else that takes a picture.
 * <p>
 * Gathered here rather than spread across the classes that need it so there is a single answer to
 * "where does this plugin write", both for a reviewer and for anyone changing it later.
 */
public final class BotwFiles
{
	/** Named for the plugin as the hub knows it, so the folder is identifiable from the outside. */
	private static final File ROOT = new File(RuneLite.RUNELITE_DIR, "botw");

	private BotwFiles()
	{
	}

	/**
	 * Where a challenge's screenshots go — one folder per challenge, because the question people ask is
	 * "who has proof of that visage on the Vorkath week", not "what happened in March".
	 *
	 * @param challengeName as the creator typed it, so it is already safe for a folder name
	 */
	public static File screenshots(String challengeName)
	{
		return new File(new File(ROOT, "screenshots"), challengeName);
	}

	/** Where an evidence export lands. */
	public static File exports()
	{
		return new File(ROOT, "exports");
	}
}

package com.botw;

import com.botw.net.BotwApi;
import com.botw.track.Screenshotter;
import com.botw.ui.BotwPanel;
import com.botw.track.ChallengeStore;
import com.botw.track.EventSender;
import com.botw.track.KillTracker;
import com.botw.track.Outbox;
import com.botw.track.WeeklyTracker;
import com.google.inject.Provides;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = BotwPlugin.NAME,
	description = "Track clan boss, raid, skill, clue and minigame challenges",
	tags = {"boss", "clan", "event", "competition", "leaderboard", "drops", "kc", "skill", "minigame"}
)
public class BotwPlugin extends Plugin
{
	public static final String NAME = "Challenge of the Week";

	@Inject
	private Client client;

	@Inject
	private EventBus eventBus;

	@Inject
	private ChallengeStore challenges;

	@Inject
	private Outbox outbox;

	@Inject
	private KillTracker killTracker;

	@Inject
	private WeeklyTracker weeklyTracker;

	@Inject
	private EventSender sender;

	@Inject
	private BotwPanel panel;

	@Inject
	private Screenshotter screenshotter;

	@Inject
	private BotwApi api;

	@Inject
	private BotwConfig config;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private ClientToolbar clientToolbar;

	private NavigationButton navigationButton;

	@Provides
	BotwConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BotwConfig.class);
	}

	@Override
	protected void startUp()
	{
		// The tracker is registered by hand rather than being a plugin of its own, so that it stops
		// listening the moment this plugin is switched off.
		eventBus.register(killTracker);
		eventBus.register(weeklyTracker);

		challenges.load();
		outbox.load();

		panel.setPlayerName(this::localPlayerName);

		// The panel refreshes itself once points land, so an open leaderboard catches up without the
		// player pressing anything.
		sender.setOnSent(panel::onPointsSent);
		sender.start();

		// Evidence goes to the creator on a background thread. Best effort by design: the full-size
		// copy is already on the player's disk, so a failed upload costs a thumbnail rather than proof.
		screenshotter.setUploader((code, eventId, itemName, jpeg) -> executor.execute(() ->
		{
			String token = challenges.participantTokenFor(code);
			if (token == null)
			{
				return;
			}

			BotwApi.Result<BotwApi.Snapshot> result = api.uploadShot(
				config.serverUrl(), code, token, eventId, itemName, System.currentTimeMillis(), jpeg);

			if (!result.ok())
			{
				log.debug("Could not upload evidence for {}: {}", itemName, result.getError());
			}
		}));

		navigationButton = NavigationButton.builder()
			.tooltip(NAME)
			.icon(ImageUtil.loadImageResource(BotwPlugin.class, "sidebar-icon.png"))
			.priority(7)
			.panel(panel)
			.build();

		clientToolbar.addNavigation(navigationButton);
	}

	@Override
	protected void shutDown()
	{
		weeklyTracker.reset();
		sender.stop();
		eventBus.unregister(killTracker);
		eventBus.unregister(weeklyTracker);
		clientToolbar.removeNavigation(navigationButton);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING
			|| state == GameState.CONNECTION_LOST || state == GameState.LOGGING_IN)
		{
			weeklyTracker.reset();
		}
		if (state != GameState.LOGGED_IN)
		{
			return;
		}

		// Both are stored per account, so they cannot be read until there is an account to read them
		// for. Logging in on a second character has to swap them over, not merge them.
		challenges.load();
		outbox.load();

		// And the panel has to be told. It is built at start-up, before there is an account, so without
		// this it goes on showing the empty list it was born with until something else happens to
		// rebuild it — which is why the challenges only turned up after a trip through Create or Join.
		panel.refreshList();

		// A backlog from an earlier session goes out now rather than waiting for the next timer.
		sender.flush();
	}

	/**
	 * The name points are reported under. Null until logged in, which is why nothing is sent before
	 * then — a kill by "nobody" cannot be put on a leaderboard.
	 */
	public String localPlayerName()
	{
		return client.getLocalPlayer() == null ? null : client.getLocalPlayer().getName();
	}
}

package com.botw;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class BotwPluginTest
{
