package com.botw.data;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * The bosses that can be picked, and the drops each is known for.
 * <p>
 * Bundled rather than fetched, so creating a challenge works offline and the wiki is not asked for the
 * same thing by every member of a clan. See {@code scripts/generate-boss-drops.mjs} for where it comes
 * from.
 * <p>
 * The uniques are a starting point, not a ruling. They are inferred from drop rarity, which catches
 * the pets and the visages but also lets the odd bolt tip through, so the create screen lets the list
 * be edited. Saving the creator typing out sixteen items matters more than being right about the
 * seventeenth.
 * <p>
 * The pet names are kept separately from the bosses because a pet is not announced like other loot.
 * The game says one has dropped without saying which, so the tracker has to work that out from the
 * challenge, and this is the list it works it out against. See {@link #petIn}.
 */
@Slf4j
@Singleton
public class BossDrops
{
	private static final String RESOURCE = "/com/botw/boss-drops.json";

	private final List<Boss> bosses;
	private final String attribution;

	/** Lowercased, because a rule's name is typed by the creator and a drop's comes from the game. */
	private final Set<String> pets;

	@Inject
	private BossDrops(Gson gson)
	{
		File file = load(gson);
		this.bosses = file.bosses == null ? Collections.emptyList() : file.bosses;
		this.attribution = file.attribution == null ? "" : file.attribution;
		this.pets = lowercased(file.pets);
	}

	private static Set<String> lowercased(List<String> names)
	{
		Set<String> set = new HashSet<>();

		if (names != null)
		{
			for (String name : names)
			{
				if (name != null && !name.trim().isEmpty())
				{
					set.add(name.trim().toLowerCase(Locale.ROOT));
				}
			}
		}

		return set;
	}

	private static File load(Gson gson)
	{
		try (InputStream stream = BossDrops.class.getResourceAsStream(RESOURCE))
		{
			if (stream == null)
			{
				log.warn("Boss data is missing; no boss can be picked");
				return new File();
			}

			File file = gson.fromJson(new InputStreamReader(stream, StandardCharsets.UTF_8), File.class);
			return file == null ? new File() : file;
		}
		catch (IOException | JsonSyntaxException e)
		{
			log.warn("Could not read the boss data", e);
			return new File();
		}
	}

	public List<Boss> all()
	{
		return Collections.unmodifiableList(bosses);
	}

	/**
	 * Required credit for the wiki's data.
	 */
	public String getAttribution()
	{
		return attribution;
	}

	/**
	 * Bosses whose name contains this, case-insensitively. An empty query returns everything, so the
	 * list is browsable before anything is typed.
	 */
	public List<Boss> search(String query)
	{
		String needle = query == null ? "" : query.trim().toLowerCase(Locale.ROOT);
		List<Boss> matches = new ArrayList<>();

		for (Boss boss : bosses)
		{
			if (needle.isEmpty() || boss.getName().toLowerCase(Locale.ROOT).contains(needle))
			{
				matches.add(boss);
			}
		}

		return matches;
	}

	/** Whether this item is somebody's pet. Every pet in the game, not only the ones bosses drop. */
	public boolean isPet(String itemName)
	{
		return itemName != null && pets.contains(itemName.trim().toLowerCase(Locale.ROOT));
	}

	/**
	 * The pet this challenge counts, or null if it counts none.
	 * <p>
	 * Needed because the game announces a pet without naming it — "you have a funny feeling like you're
	 * being followed" and nothing more. What dropped therefore has to be worked out rather than read,
	 * and the challenge's own list is what it is worked out from: a Vorkath challenge that scores Vorki
	 * can only have meant Vorki.
	 * <p>
	 * Reading the challenge rather than the boss is deliberate. Half the raid bosses came out of the
	 * wiki with no uniques at all, so their creators type the pet in by hand — and going by the boss
	 * would leave exactly those challenges unable to score the pet they were set up for.
	 */
	public String petIn(Challenge challenge)
	{
		return petIn(challenge, pets);
	}

	/**
	 * @param pets lowercased pet names
	 * @return the one pet the challenge scores, or null where there is no single answer
	 */
	static String petIn(Challenge challenge, Set<String> pets)
	{
		if (challenge == null || challenge.getDrops() == null)
		{
			return null;
		}

		String found = null;

		for (DropRule rule : challenge.getDrops())
		{
			if (rule == null || rule.getName() == null || rule.getPoints() <= 0
				|| !pets.contains(rule.getName().trim().toLowerCase(Locale.ROOT)))
			{
				continue;
			}

			// Two pets on one challenge is not something a boss can produce, and guessing between them
			// would be inventing a drop nobody had. Better to score nothing than the wrong thing.
			if (found != null)
			{
				return null;
			}

			found = rule.getName();
		}

		return found;
	}

	public Boss byName(String name)
	{
		for (Boss boss : bosses)
		{
			if (boss.getName().equalsIgnoreCase(name))
			{
				return boss;
			}
		}

		return null;
	}

	/**
	 * One boss and the drops it is known for.
	 */
	public static class Boss
	{
		private String name = "";
		private List<Unique> uniques = new ArrayList<>();

		public String getName()
		{
			return name;
		}

		public List<Unique> getUniques()
		{
			return uniques == null ? Collections.emptyList() : uniques;
		}

		@Override
		public String toString()
		{
			return name;
		}
	}

	public static class Unique
	{
		private String name = "";
		private String rarity = "";
		private int oneIn;

		/**
		 * Resolved at build time, because the plugin's own item search reads the price API and that only
		 * knows tradeable things — every pet came out without an icon, which is the half of the list
		 * people care about most.
		 */
		private int itemId = -1;

		public String getName()
		{
			return name;
		}

		/** As the wiki writes it, e.g. "1/3000". Shown so the creator can judge what it is worth. */
		public String getRarity()
		{
			return rarity;
		}

		public int getOneIn()
		{
			return oneIn;
		}

		public int getItemId()
		{
			return itemId;
		}
	}

	/** Mirrors the generated JSON. */
	private static class File
	{
		int dataVersion;
		String source;
		String attribution;
		String generatedAt;
		List<String> pets = new ArrayList<>();
		List<Boss> bosses = new ArrayList<>();
	}
}

package com.botw.data;

import java.util.ArrayList;
import java.util.List;
import java.util.LinkedHashMap;
import java.util.Map;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * One weekly challenge, exactly as the service describes it.
 * <p>
 * A plain class with a no-arg constructor because this is read from JSON, both from the service and
 * from the local copy kept between sessions.
 */
@Data
@NoArgsConstructor
public class Challenge
{
	/** What people type to join. Six characters, no letters that look like digits. */
	private String code = "";

	private String name = "";
	private String boss = "";

	/** Epoch milliseconds, both. The timezone below is only for showing the creator what they chose. */
	private long startsAt;
	private long endsAt;

	private String timezone = "UTC";

	/** Every {@code kcPer} kills is worth {@code kcPoints}. Both are the creator's choice. */
	private int kcPer = 10;
	private int kcPoints = 1;

	private List<DropRule> drops = new ArrayList<>();

	private ChallengeType eventType = ChallengeType.BOSS;
	private boolean raidByPoints;
	private Map<String, Integer> raidPoints = new LinkedHashMap<>();
	private List<PrizeCandidate> prizeCandidates = new ArrayList<>();

	public String scoreUnit()
	{
		switch (eventType)
		{
			case SKILL: return "XP";
			case CLUE: return "clues";
			case MINIGAME: return drops.stream().anyMatch(rule -> dropPoints(rule) > 0) ? "points" : minigameUnit();
			case RAID: return raidByPoints ? "points" : "clears";
			default: return "points";
		}
	}

	public String minigameUnit()
	{
		MinigameTarget target = MinigameTarget.forName(boss);
		return target == null ? "completions" : target.unit;
	}

	public int dropPoints(DropRule rule)
	{
		return eventType == ChallengeType.MINIGAME && !rule.isPointsEnabled() ? 0 : rule.getPoints();
	}

	public boolean tracksDrop(DropRule rule)
	{
		return dropPoints(rule) > 0 || rule.isFirstPrize() || rule.isPurple();
	}

	public boolean matchesDrop(String itemName)
	{
		return drops.stream().anyMatch(rule -> rule.getName().equalsIgnoreCase(itemName)
			&& tracksDrop(rule));
	}

	private String creatorRsn = "";

	public boolean hasStarted(long now)
	{
		return now >= startsAt;
	}

	public boolean hasEnded(long now)
	{
		return now > endsAt;
	}

	/**
	 * Whether kills happening right now count. Everything the tracker does hangs off this.
	 */
	public boolean isRunning(long now)
	{
		return hasStarted(now) && !hasEnded(now);
	}

	/**
	 * The points a named item is worth, or zero if the challenge does not count it.
	 * <p>
	 * Matched without case because a drop's name comes from the game while the rule's came from the
	 * wiki, and the two do not always agree on capitalisation.
	 */
	public int pointsForDrop(String itemName)
	{
		for (DropRule rule : drops)
		{
			if (rule.getName().equalsIgnoreCase(itemName))
			{
				return dropPoints(rule);
			}
		}

		return 0;
	}

	public boolean counts(String itemName)
	{
		return matchesDrop(itemName);
	}
}

package com.botw.data;

/** The event format is fixed after a challenge is created. */
public enum ChallengeType
{
	BOSS("Boss of the Week"),
	RAID("Raid of the Week"),
	SKILL("Skill of the Week"),
	CLUE("Clue of the Week"),
	MINIGAME("Skill Minigame of the Week");

	private final String title;

	ChallengeType(String title)
	{
		this.title = title;
	}

	public String title()
	{
		return title;
	}
}

package com.botw.data;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * One drop the challenge counts, and what it is worth.
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class DropRule
{
	private String name = "";

	/**
	 * Used only to draw the item's icon. Matching is done on the name, because that is what the game
	 * hands us when something drops and it is what the creator sees when setting the points.
	 */
	private int itemId = -1;

	private int points;
	private boolean firstPrize;
	private boolean purple;
	private boolean pointsEnabled;

	public DropRule(String name, int itemId, int points)
	{
		this(name, itemId, points, false, false);
	}

	public DropRule(String name, int itemId, int points, boolean firstPrize, boolean purple)
	{
		this(name, itemId, points, firstPrize, purple, false);
	}
}

package com.botw.data;

import java.util.LinkedHashMap;
import java.util.Map;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * One row of the leaderboard, as the service computes it.
 */
@Data
@NoArgsConstructor
public class LeaderboardEntry
{
	private String rsn = "";
	private int points;
	private int kills;
	private int drops;
	private int levels;
	private int purples;
	private Map<String, Integer> raidModes = new LinkedHashMap<>();

	/**
	 * Added by the creator rather than having joined from a plugin — a mobile player, whose kills
	 * nobody can see. Shown on their row, because a total that was typed in should not be passed off
	 * as one that was counted.
	 */
	private boolean manual;

	/** What the creator has added or taken away by hand. Zero for almost everyone. */
	private int adjustment;
}

package com.botw.data;

import java.util.Arrays;
import java.util.Locale;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarPlayerID;

/** Activity-specific score units and the loot sources RuneLite reports. */
public enum MinigameTarget
{
	RIFT("Guardians of the Rift", "rifts", "Count a successful rift close. Reward searches are separate.",
		26822, -1, "", new String[] {"Guardians of the Rift"},
		new String[] {"Abyssal needle", "Abyssal lantern", "Abyssal protector"}, "Abyssal protector"),
	VALE("Vale Totems", "rolls", "One roll per 100 Vale offerings rummaged. Banked offerings can be used.",
		31054, -1, "", new String[] {"Vale offerings"},
		new String[] {"Fletching knife", "Bow string spool", "Greenman mask"}, ""),
	MINE("Volcanic Mine", "runs", "Count exits that award the run's Mining XP. Ore packs are separate.",
		27693, -1, "", new String[] {"Ore Pack (Volcanic Mine)"},
		new String[] {"Dragon pickaxe (broken)"}, ""),
	SEPULCHRE("Hallowed Sepulchre", "floors", "Each completed floor counts. Coffin drops are separate.",
		24711, -1, "", new String[] {"Hallowed Sepulchre Coffin", "Hallowed Sepulchre Grand Coffin", "Grand Hallowed Coffin"},
		new String[] {"Ring of endurance (uncharged)", "Strange old lockpick (full)", "Strange hallowed tome", "Giant squirrel"}, "Giant squirrel"),
	GAUNTLET("The Gauntlet", "clears", "Count regular Gauntlet clears. Corrupted has its own event.",
		23859, VarPlayerID.TOTAL_COMPLETED_GAUNTLET, "Gauntlet", new String[] {"Gauntlet", "The Gauntlet", "Crystalline Hunllef"},
		new String[] {"Enhanced crystal weapon seed", "Crystal armour seed", "Crystal weapon seed", "Youngllef"}, "Youngllef"),
	CORRUPTED("Corrupted Gauntlet", "clears", "Count Corrupted Gauntlet clears only.",
		23759, VarPlayerID.TOTAL_COMPLETED_GAUNTLET_HM, "Corrupted Gauntlet",
		new String[] {"Corrupted Gauntlet", "The Corrupted Gauntlet", "Corrupted Hunllef"},
		new String[] {"Enhanced crystal weapon seed", "Crystal armour seed", "Crystal weapon seed", "Youngllef"}, "Youngllef"),
	ZALCANO("Zalcano", "kills", "Count your credited Zalcano kills.",
		23908, VarPlayerID.TOTAL_ZALCANO_KILLS, "Zalcano", new String[] {"Zalcano"},
		new String[] {"Crystal tool seed", "Zalcano shard", "Uncut onyx", "Smolcano"}, "Smolcano"),
	TEMPOROSS("Tempoross", "wins", "Count successful Tempoross rounds. Reward permits are separate.",
		25582, VarPlayerID.TOTAL_TEMPOROSS_KILLS, "Tempoross", new String[] {"Reward pool (Tempoross)", "Casket (Tempoross)"},
		new String[] {"Fish barrel", "Tackle box", "Big harpoonfish", "Tome of Water (empty)", "Dragon harpoon", "Tiny tempor"}, "Tiny tempor"),
	WINTERTODT("Wintertodt", "wins", "Count successful Wintertodt rounds. Reward cart searches are separate.",
		ItemID.PHOENIXPET, VarPlayerID.TOTAL_WINTERTODT_KILLS, "Wintertodt",
		new String[] {"Reward cart (Wintertodt)", "Supply crate (Wintertodt)"},
		new String[] {"Phoenix", "Tome of Fire (empty)", "Bruma torch", "Warm gloves",
			"Pyromancer hood", "Pyromancer garb", "Pyromancer robe", "Pyromancer boots"}, "Phoenix");

	public final String title;
	public final String unit;
	public final String description;
	public final int icon;
	public final int varp;
	private final String completionName;
	private final String[] lootSources;
	private final String[] rewards;
	public final String pet;

	MinigameTarget(String title, String unit, String description, int icon, int varp, String completionName,
		String[] lootSources, String[] rewards, String pet)
	{
		this.title = title;
		this.unit = unit;
		this.description = description;
		this.icon = icon;
		this.varp = varp;
		this.completionName = completionName;
		this.lootSources = lootSources;
		this.rewards = rewards;
		this.pet = pet;
	}

	public static MinigameTarget forName(String name)
	{
		return Arrays.stream(values()).filter(target -> target.title.equalsIgnoreCase(name)).findFirst().orElse(null);
	}

	public static String[] names()
	{
		return Arrays.stream(values()).map(target -> target.title).toArray(String[]::new);
	}

	public boolean matchesLoot(String source)
	{
		return Arrays.stream(lootSources).anyMatch(name -> name.equalsIgnoreCase(source));
	}

	public boolean usesServerLoot()
	{
		return this == SEPULCHRE || this == GAUNTLET || this == CORRUPTED || this == ZALCANO;
	}

	public boolean matchesCompletion(String name)
	{
		return !completionName.isEmpty() && (completionName.equalsIgnoreCase(name)
			|| ("the " + completionName.toLowerCase(Locale.ROOT)).equals(name.toLowerCase(Locale.ROOT)));
	}

	public String[] rewards()
	{
		return rewards.clone();
	}
}

