public final class WeeklyTargets
{
	public static final String COX = "Chambers of Xeric";
	public static final String TOB = "Theatre of Blood";
	public static final String TOA = "Tombs of Amascut";
	public static final String ARCHIVE = "The Fractured Archive";
	public static final String RIFT = "Guardians of the Rift";

	public static final String[] RAIDS = { COX, TOB, TOA, ARCHIVE };
	public static final String[] CLUES = { "Beginner", "Easy", "Medium", "Hard", "Elite", "Master" };

	private WeeklyTargets()
	{
	}

	public static String[] skills()
	{
		return Arrays.stream(Skill.values()).filter(skill -> !skill.name().equals("OVERALL"))
			.map(Skill::getName).toArray(String[]::new);
	}

	public static Skill skill(String name)
	{
		return Arrays.stream(Skill.values()).filter(skill -> skill.getName().equalsIgnoreCase(name))
			.findFirst().orElse(null);
	}

	public static boolean tracksWorld(Client client)
	{
		java.util.Set<WorldType> types = client.getWorldType();
		return !types.contains(WorldType.BETA_WORLD) && !types.contains(WorldType.DEADMAN)
			&& !types.contains(WorldType.SEASONAL) && !types.contains(WorldType.TOURNAMENT_WORLD)
			&& !types.contains(WorldType.FRESH_START_WORLD);
	}

	public static List<String> modes(String target)
	{
		switch (target)
		{
			case COX: return Arrays.asList("Normal", "Challenge");
			case TOB: return Arrays.asList("Entry", "Normal", "Hard");
			case TOA: return Arrays.asList("Entry", "Normal", "Expert");
			case ARCHIVE: return Collections.singletonList("Normal");
			default: return Collections.emptyList();
		}
	}

	public static boolean raidSource(String target, String source)
	{
		String name = source.toLowerCase(Locale.ROOT);
		return name.startsWith(target.toLowerCase(Locale.ROOT))
			|| (ARCHIVE.equals(target) && name.startsWith("fractured archive"));
	}

	/** Names used in the game's completion messages. */
	public static String raidMode(String target, String source)
	{
		if (!raidSource(target, source))
		{
			return null;
		}
		String name = source.toLowerCase(Locale.ROOT);
		if (name.contains("entry") || name.contains("story")) return "Entry";
		if (TOA.equals(target) && name.contains("expert")) return "Expert";
		if (TOB.equals(target) && name.contains("hard")) return "Hard";
		if (COX.equals(target) && name.contains("challenge")) return "Challenge";
		return "Normal";
	}

	public static String[] purpleDrops(String raid)
	{
		switch (raid)
		{
			case COX:
				return new String[] {"Dexterous prayer scroll", "Arcane prayer scroll", "Twisted buckler",
					"Dragon hunter crossbow", "Dinh's bulwark", "Ancestral hat", "Ancestral robe top",
					"Ancestral robe bottom", "Dragon claws", "Elder maul", "Kodai insignia", "Twisted bow"};
			case TOB:
				return new String[] {"Avernic defender hilt", "Ghrazi rapier", "Sanguinesti staff (uncharged)",
					"Justiciar faceguard", "Justiciar chestguard", "Justiciar legguards", "Scythe of vitur (uncharged)"};
			case TOA:
				return new String[] {"Osmumten's fang", "Lightbearer", "Elidinis' ward", "Masori mask",
					"Masori body", "Masori chaps", "Tumeken's shadow (uncharged)"};
			case ARCHIVE:
				return new String[] {"Rondache", "Zorya's tome (uncharged)", "Ascension crossbows", "Obligator"};
			default: return new String[0];
		}
	}

	public static String raidPet(String raid)
	{
		switch (raid)
		{
			case COX: return "Olmlet";
			case TOB: return "Lil' zik";
			case TOA: return "Tumeken's guardian";
			case ARCHIVE: return "Orion";
			default: return "";
		}
	}
}

package com.botw.net;

import com.botw.data.Challenge;
import com.botw.data.ChallengeType;
import com.botw.data.DropRule;
import com.botw.data.LeaderboardEntry;
import com.botw.track.PendingEvent;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import java.io.IOException;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.Base64;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Talks to the service the plugins share.
 * <p>
 * Every call here blocks and must be made off the client thread. The panel runs them on the executor
 * and updates itself afterwards, because a request that hangs on the client thread freezes the game.
 * <p>
 * Failures come back as a {@link Result} carrying a message rather than as an exception. A challenge
 * failing to load is an ordinary thing — someone typed a code wrong, or the network is down — and the
 * panel needs to say so rather than swallow it.
 */
@Slf4j
@Singleton
public class BotwApi
{
	private static final MediaType JSON = MediaType.get("application/json");

	private final OkHttpClient httpClient;
	private final Gson gson;

	@Inject
	private BotwApi(OkHttpClient httpClient, Gson gson)
	{
		this.httpClient = httpClient;
		this.gson = gson;
	}

	/**
	 * Either what was asked for, or why not.
	 */
	@Value
	public static class Result<T>
	{
		T value;
		String error;

		/**
		 * The service answered, and said there is no such thing.
		 * <p>
		 * Kept apart from every other failure because the two call for opposite responses. A challenge
		 * that is gone should be cleared off the player's list; a challenge that merely could not be
		 * reached — no connection, server restarting — must be left exactly where it is. Treating the
		 * second as the first would quietly delete somebody's competition because their wifi dropped.
		 */
		boolean gone;

		public boolean ok()
		{
			return error == null;
		}

		static <T> Result<T> of(T value)
		{
			return new Result<>(value, null, false);
		}

		static <T> Result<T> failed(String error)
		{
			return new Result<>(null, error, false);
		}

		static <T> Result<T> gone(String error)
		{
			return new Result<>(null, error, true);
		}
	}

	/**
	 * A challenge and its leaderboard, which always travel together — there is no screen that wants one
	 * without the other.
	 */
	@Value
	public static class Snapshot
	{
		Challenge challenge;
		List<LeaderboardEntry> leaderboard;

		/** Only present when the challenge was just created or joined. */
		String creatorToken;
		String participantToken;

		/** Null when this challenge has no Discord board. */
		Integer discordRankLimit;
	}

	public Result<Snapshot> create(String baseUrl, Challenge challenge, String creatorRsn)
	{
		JsonObject body = new JsonObject();
		body.addProperty("name", challenge.getName());
		body.addProperty("boss", challenge.getBoss());
		body.addProperty("startsAt", challenge.getStartsAt());
		body.addProperty("endsAt", challenge.getEndsAt());
		body.addProperty("timezone", challenge.getTimezone());
		body.addProperty("kcPer", challenge.getKcPer());
		body.addProperty("kcPoints", challenge.getKcPoints());
		body.addProperty("creatorRsn", creatorRsn);
		body.add("drops", gson.toJsonTree(challenge.getDrops()));
		body.addProperty("eventType", challenge.getEventType().name());
		body.addProperty("raidByPoints", challenge.isRaidByPoints());
		body.add("raidPoints", gson.toJsonTree(challenge.getRaidPoints()));

		boolean weekly = challenge.getEventType() != ChallengeType.BOSS;
		// Older Workers accept extra JSON fields on /challenges. Use a new path so they cannot
		// silently save a raid or skill event as a boss challenge.
		Result<Snapshot> result = send(new Request.Builder()
			.url(url(baseUrl, "v1", weekly ? "weekly-challenges" : "challenges"))
			.post(RequestBody.create(JSON, gson.toJson(body))));
		return weekly && result.isGone()
			? Result.failed("This server does not support weekly events yet. Check the server address in the plugin settings.")
			: result;
	}

	public Result<Snapshot> read(String baseUrl, String code)
	{
		return send(new Request.Builder()
			.url(url(baseUrl, "v1", "challenges", code))
			.get());
	}

	public Result<Snapshot> join(String baseUrl, String code, String rsn)
	{
		JsonObject body = new JsonObject();
		body.addProperty("rsn", rsn);

		return send(new Request.Builder()
			.url(url(baseUrl, "v1", "challenges", code, "join"))
			.post(RequestBody.create(JSON, gson.toJson(body))));
	}

	public Result<Snapshot> update(String baseUrl, Challenge challenge, String creatorToken)
	{
		JsonObject body = new JsonObject();
		body.addProperty("name", challenge.getName());
		body.addProperty("boss", challenge.getBoss());
		body.addProperty("startsAt", challenge.getStartsAt());
		body.addProperty("endsAt", challenge.getEndsAt());
		body.addProperty("timezone", challenge.getTimezone());
		body.addProperty("kcPer", challenge.getKcPer());
		body.addProperty("kcPoints", challenge.getKcPoints());
		body.add("drops", gson.toJsonTree(challenge.getDrops()));
		body.addProperty("eventType", challenge.getEventType().name());
		body.addProperty("raidByPoints", challenge.isRaidByPoints());
		body.add("raidPoints", gson.toJsonTree(challenge.getRaidPoints()));

		return send(new Request.Builder()
			.url(url(baseUrl, "v1", "challenges", challenge.getCode()))
			.patch(RequestBody.create(JSON, gson.toJson(body)))
			.header("X-Creator-Token", creatorToken));
	}

	public Result<Snapshot> delete(String baseUrl, String code, String creatorToken)
	{
		return send(new Request.Builder()
			.url(url(baseUrl, "v1", "challenges", code))
			.delete()
			.header("X-Creator-Token", creatorToken));
	}

	/** The webhook URL goes only to the BOTW service; it must never appear in public challenge data. */
	public Result<Boolean> connectDiscord(
		String baseUrl, String code, String creatorToken, String webhookUrl, int rankLimit)
	{
		JsonObject body = new JsonObject();
		if (webhookUrl != null)
		{
			body.addProperty("webhookUrl", webhookUrl);
		}
		body.addProperty("rankLimit", rankLimit);
		return sendDiscord(new Request.Builder()
			.url(url(baseUrl, "v1", "challenges", code, "discord"))
			.put(RequestBody.create(JSON, gson.toJson(body)))
			.header("X-Creator-Token", creatorToken));
	}

	public Result<Boolean> removeDiscord(String baseUrl, String code, String creatorToken)
	{
		return sendDiscord(new Request.Builder()
			.url(url(baseUrl, "v1", "challenges", code, "discord"))
			.delete()
			.header("X-Creator-Token", creatorToken));
	}

	private Result<Boolean> sendDiscord(Request.Builder builder)
	{
		try (Response response = httpClient.newCall(builder.build()).execute())
		{
			ResponseBody body = response.body();
			String text = body == null ? "" : body.string();
			return response.isSuccessful()
				? Result.of(Boolean.TRUE)
				: Result.failed(messageIn(text, "Discord setup failed (" + response.code() + ")"));
		}
		catch (IOException e)
		{
			// The URL is a secret; do not log the request or exception.
			return Result.failed("Could not reach the server");
		}
	}

	/**
	 * Puts someone on the leaderboard who will never report anything themselves.
	 * <p>
	 * A mobile player cannot run a plugin, so their kills cannot be counted. The clan handles them the
	 * way it always has — screenshots, and a number entered by staff — and this is where that number
	 * goes, so they appear on the same board as everyone else.
	 */
	public Result<Snapshot> addParticipant(
		String baseUrl, String code, String creatorToken, String rsn, int points)
	{
		JsonObject body = new JsonObject();
		body.addProperty("rsn", rsn);
		body.addProperty("points", points);

		return send(new Request.Builder()
			.url(url(baseUrl, "v1", "challenges", code, "participants"))
			.post(RequestBody.create(JSON, gson.toJson(body)))
			.header("X-Creator-Token", creatorToken));
	}

	/**
	 * Sets someone's total.
	 * <p>
	 * A total rather than a change, because that is how a creator thinks about it. What the service
	 * keeps is the difference from the player's own tracked score, so their kills go on counting
	 * underneath this.
	 */
	public Result<Snapshot> setPoints(
		String baseUrl, String code, String creatorToken, String rsn, int points)
	{
		JsonObject body = new JsonObject();
		body.addProperty("points", points);

		return send(new Request.Builder()
			.url(url(baseUrl, "v1", "challenges", code, "participants", rsn))
			.patch(RequestBody.create(JSON, gson.toJson(body)))
			.header("X-Creator-Token", creatorToken));
	}

	/** Takes someone off the leaderboard, for when a name was added wrong. */
	public Result<Snapshot> removeParticipant(
		String baseUrl, String code, String creatorToken, String rsn)
	{
		return send(new Request.Builder()
			.url(url(baseUrl, "v1", "challenges", code, "participants", rsn))
			.delete()
			.header("X-Creator-Token", creatorToken));
	}

	/**
	 * Reports what happened. The events keep their ids, so a batch that is sent twice counts once.
	 */
	public Result<Snapshot> submit(
		String baseUrl, String code, String participantToken, List<PendingEvent> events)
	{
		JsonObject body = new JsonObject();
		body.add("events", gson.toJsonTree(events));

		return send(new Request.Builder()
			.url(url(baseUrl, "v1", "challenges", code, "events"))
			.post(RequestBody.create(JSON, gson.toJson(body)))
			.header("X-Participant-Token", participantToken));
	}

	/**
	 * One screenshot, as evidence the creator can look at without asking anyone for it.
	 */
	public Result<Snapshot> uploadShot(
		String baseUrl, String code, String participantToken, String eventId, String itemName,
		long occurredAt, byte[] jpeg)
	{
		JsonObject body = new JsonObject();
		body.addProperty("eventId", eventId);
		body.addProperty("itemName", itemName);
		body.addProperty("occurredAt", occurredAt);
		body.addProperty("image", Base64.getEncoder().encodeToString(jpeg));

		return send(new Request.Builder()
			.url(url(baseUrl, "v1", "challenges", code, "shots"))
			.post(RequestBody.create(JSON, gson.toJson(body)))
			.header("X-Participant-Token", participantToken));
	}

	/**
	 * What evidence exists, without the pictures. Creator only.
	 */
	public Result<List<Shot>> listShots(String baseUrl, String code, String creatorToken)
	{
		Request request = new Request.Builder()
			.url(url(baseUrl, "v1", "challenges", code, "shots"))
			.get()
			.header("X-Creator-Token", creatorToken)
			.build();

		try (Response response = httpClient.newCall(request).execute())
		{
			ResponseBody responseBody = response.body();
			String text = responseBody == null ? "" : responseBody.string();

			if (!response.isSuccessful())
			{
				return Result.failed(messageIn(text, "Could not load the evidence"));
			}

			JsonObject root = gson.fromJson(text, JsonObject.class);
			Type type = new TypeToken<List<Shot>>()
			{
			}.getType();

			List<Shot> shots = root != null && root.has("shots")
				? gson.fromJson(root.get("shots"), type)
				: new ArrayList<>();

			return Result.of(shots == null ? new ArrayList<>() : shots);
		}
		catch (IOException e)
		{
			return Result.failed("Could not reach the server");
		}
		catch (JsonSyntaxException e)
		{
			return Result.failed("The server sent something unreadable");
		}
	}

	/**
	 * One picture, fetched only when it is opened. A hundred thumbnails in one response would be
	 * several megabytes for a screen most of which is never looked at.
	 */
	public Result<byte[]> readShot(String baseUrl, String code, String creatorToken, String eventId)
	{
		Request request = new Request.Builder()
			.url(url(baseUrl, "v1", "challenges", code, "shots", eventId))
			.get()
			.header("X-Creator-Token", creatorToken)
			.build();

		try (Response response = httpClient.newCall(request).execute())
		{
			ResponseBody responseBody = response.body();
			String text = responseBody == null ? "" : responseBody.string();

			if (!response.isSuccessful())
			{
				return Result.failed(messageIn(text, "Could not load that screenshot"));
			}

			JsonObject root = gson.fromJson(text, JsonObject.class);
			if (root == null || !root.has("image"))
			{
				return Result.failed("That screenshot is missing");
			}

			return Result.of(Base64.getDecoder().decode(root.get("image").getAsString()));
		}
		catch (IOException e)
		{
			return Result.failed("Could not reach the server");
		}
		catch (JsonSyntaxException | IllegalArgumentException e)
		{
			return Result.failed("That screenshot is unreadable");
		}
	}

	/** One piece of evidence, without its picture. */
	@lombok.Data
	public static class Shot
	{
		private String eventId = "";
		private String rsn = "";
		private String itemName = "";
		private long occurredAt;
	}

	private Result<Snapshot> send(Request.Builder builder)
	{
		try (Response response = httpClient.newCall(builder.build()).execute())
		{
			ResponseBody responseBody = response.body();
			String text = responseBody == null ? "" : responseBody.string();

			if (!response.isSuccessful())
			{
				String message = messageIn(text, "The server said no (" + response.code() + ")");
				return response.code() == 404 ? Result.gone(message) : Result.failed(message);
			}

			return Result.of(parse(text));
		}
		catch (IOException e)
		{
			log.debug("Request failed", e);
			return Result.failed("Could not reach the server");
		}
		catch (JsonSyntaxException e)
		{
			log.warn("Unreadable response", e);
			return Result.failed("The server sent something unreadable");
		}
	}

	private Snapshot parse(String text)
	{
		JsonObject root = gson.fromJson(text, JsonObject.class);
		if (root == null)
		{
			return new Snapshot(null, new ArrayList<>(), null, null, null);
		}

		Challenge challenge = root.has("challenge") && !root.get("challenge").isJsonNull()
			? gson.fromJson(root.get("challenge"), Challenge.class)
			: null;

		List<LeaderboardEntry> leaderboard = new ArrayList<>();
		if (root.has("leaderboard") && root.get("leaderboard").isJsonArray())
		{
			Type type = new TypeToken<List<LeaderboardEntry>>()
			{
			}.getType();

			List<LeaderboardEntry> parsed = gson.fromJson(root.get("leaderboard"), type);
			if (parsed != null)
			{
				leaderboard.addAll(parsed);
			}
		}

		// The code comes back at the top level on create, where the challenge does not carry it yet.
		if (challenge != null && (challenge.getCode() == null || challenge.getCode().isEmpty())
			&& root.has("code"))
		{
			challenge.setCode(root.get("code").getAsString());
		}

		return new Snapshot(
			challenge,
			leaderboard,
			stringOrNull(root, "creatorToken"),
			stringOrNull(root, "participantToken"),
			root.has("discordRankLimit") && !root.get("discordRankLimit").isJsonNull()
				? root.get("discordRankLimit").getAsInt() : null);
	}

	/**
	 * The server's own wording where there is one. It says "No challenge with that code", which is more
	 * use to a player than anything this class could invent.
	 */
	private String messageIn(String text, String fallback)
	{
		try
		{
			JsonObject root = gson.fromJson(text, JsonObject.class);
			if (root != null && root.has("error"))
			{
				return root.get("error").getAsString();
			}
		}
		catch (JsonSyntaxException ignored)
		{
			// Fall through to the generic message.
		}

		return fallback;
	}

	private static String stringOrNull(JsonObject root, String key)
	{
		return root.has(key) && !root.get(key).isJsonNull() ? root.get(key).getAsString() : null;
	}

	private static HttpUrl url(String baseUrl, String... segments)
	{
		HttpUrl parsed = HttpUrl.parse(baseUrl.trim());
		if (parsed == null)
		{
			throw new IllegalArgumentException("The server address is not a valid URL: " + baseUrl);
		}

		HttpUrl.Builder builder = parsed.newBuilder();
		for (String segment : segments)
		{
			builder.addPathSegment(segment);
		}

		return builder.build();
	}
}

package com.botw.track;

import com.botw.data.Challenge;
import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.annotations.SerializedName;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * The challenges this account has made or joined, and the tokens that prove it.
 * <p>
 * Kept per RuneScape account rather than per installation. Someone running an ironman alongside a main
 * is competing as two different people, and their challenges should not bleed into each other.
 * <p>
 * Tokens live here and nowhere else. The creator token is what allows a challenge to be edited and the
 * participant token is what allows points to be reported, so losing them means losing the challenge —
 * which is why they are written down the moment they arrive rather than held in memory.
 */
@Slf4j
@Singleton
public class ChallengeStore
{
	private static final String CONFIG_GROUP = "botw";
	private static final String KEY = "challenges";

	private final ConfigManager configManager;
	private final Gson gson;

	private final List<Membership> memberships = new ArrayList<>();

	@Inject
	private ChallengeStore(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	/**
	 * What this account knows about one challenge.
	 */
	public static class Membership
	{
		@SerializedName("challenge")
		public Challenge challenge = new Challenge();

		/** Present when this account created it. Lets the challenge be edited. */
		@SerializedName("creatorToken")
		public String creatorToken;

		/** Present once joined. Lets points be reported. */
		@SerializedName("participantToken")
		public String participantToken;

		public boolean isCreator()
		{
			return creatorToken != null && !creatorToken.isEmpty();
		}

		public boolean isParticipant()
		{
			return participantToken != null && !participantToken.isEmpty();
		}
	}

	public synchronized void load()
	{
		memberships.clear();

		if (configManager.getRSProfileKey() == null)
		{
			return;
		}

		String json = configManager.getRSProfileConfiguration(CONFIG_GROUP, KEY);
		if (json == null || json.isEmpty())
		{
			return;
		}

		try
		{
			Type type = new TypeToken<List<Membership>>()
			{
			}.getType();

			List<Membership> stored = gson.fromJson(json, type);
			if (stored != null)
			{
				memberships.addAll(stored);
			}
		}
		catch (JsonSyntaxException e)
		{
			// Never throw away a token because one entry is unreadable; that would silently remove
			// someone from a challenge they had already joined.
			log.warn("Could not read saved challenges", e);
		}

		log.debug("Loaded {} challenges", memberships.size());
	}

	private void save()
	{
		if (configManager.getRSProfileKey() == null)
		{
			return;
		}

		configManager.setRSProfileConfiguration(CONFIG_GROUP, KEY, gson.toJson(memberships));
	}

	public synchronized List<Membership> all()
	{
		return Collections.unmodifiableList(new ArrayList<>(memberships));
	}

	/**
	 * The challenges whose kills should be counted. Everything joined, whether or not it is running —
	 * the tracker decides that per kill, because a challenge can start while the client is open.
	 */
	public synchronized List<Challenge> joined()
	{
		List<Challenge> joined = new ArrayList<>();
		for (Membership membership : memberships)
		{
			if (membership.isParticipant())
			{
				joined.add(membership.challenge);
			}
		}

		return joined;
	}

	@Nullable
	public synchronized Membership find(String code)
	{
		for (Membership membership : memberships)
		{
			if (membership.challenge.getCode().equalsIgnoreCase(code))
			{
				return membership;
			}
		}

		return null;
	}

	/**
	 * Adds a challenge, or updates one already known. Tokens already held are kept when the incoming
	 * copy has none — a refresh from the service carries the challenge but not the secrets.
	 */
	public synchronized void put(Challenge challenge, @Nullable String creatorToken, @Nullable String participantToken)
	{
		Membership existing = find(challenge.getCode());

		if (existing == null)
		{
			existing = new Membership();
			memberships.add(existing);
		}

		existing.challenge = challenge;

		if (creatorToken != null && !creatorToken.isEmpty())
		{
			existing.creatorToken = creatorToken;
		}

		if (participantToken != null && !participantToken.isEmpty())
		{
			existing.participantToken = participantToken;
		}

		save();
	}

	public synchronized void remove(String code)
	{
		memberships.removeIf(membership -> membership.challenge.getCode().equalsIgnoreCase(code));
		save();
	}

	@Nullable
	public synchronized String participantTokenFor(String code)
	{
		Membership membership = find(code);
		return membership == null ? null : membership.participantToken;
	}

	@Nullable
	public synchronized String creatorTokenFor(String code)
	{
		Membership membership = find(code);
		return membership == null ? null : membership.creatorToken;
	}
}

package com.botw.track;

import com.botw.BotwConfig;
import com.botw.net.BotwApi;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Drains the outbox to the service.
 * <p>
 * Runs on a timer rather than sending as kills happen. A boss dies every minute or two and the
 * leaderboard is read by people, not machines — nobody needs their kill to appear within the second,
 * and batching keeps a week of killing to a few hundred requests instead of thousands.
 * <p>
 * Nothing here is on the client thread. A request that hangs would freeze the game if it were.
 */
@Slf4j
@Singleton
public class EventSender
{
	/**
	 * The safety net: catches whatever a failed send left behind, and anything held over from a
	 * previous session. Not what makes a kill appear — {@link #nudge()} does that.
	 */
	private static final int EVERY_SECONDS = 60;

	/**
	 * How long after a kill it gets sent.
	 * <p>
	 * Long enough that a boss killed three times over goes in one request rather than three, short
	 * enough that nobody waits for it. Relying on the minute sweep meant a kill could take a full
	 * minute to show, and pressing Refresh in the meantime did not help: that only re-reads the
	 * service, which had not been told yet.
	 */
	private static final int SOON_SECONDS = 5;

	private final ScheduledExecutorService executor;
	private final Outbox outbox;
	private final ChallengeStore challenges;
	private final BotwApi api;
	private final BotwConfig config;

	private ScheduledFuture<?> scheduled;

	/** The one-off send that follows a kill. Held so a burst of kills schedules one, not one each. */
	private ScheduledFuture<?> soon;

	/** Told after every successful send, so the panel can refresh without polling separately. */
	private Runnable onSent = () ->
	{
	};

	@Inject
	private EventSender(
		ScheduledExecutorService executor,
		Outbox outbox,
		ChallengeStore challenges,
		BotwApi api,
		BotwConfig config)
	{
		this.executor = executor;
		this.outbox = outbox;
		this.challenges = challenges;
		this.api = api;
		this.config = config;
	}

	public void setOnSent(Runnable onSent)
	{
		this.onSent = onSent;
	}

	public void start()
	{
		stop();

		// Anything put in the outbox from here on brings a send with it.
		outbox.setOnAdded(this::nudge);

		scheduled = executor.scheduleWithFixedDelay(
			this::flush, EVERY_SECONDS, EVERY_SECONDS, TimeUnit.SECONDS);
	}

	public void stop()
	{
		outbox.setOnAdded(() ->
		{
		});

		if (scheduled != null)
		{
			scheduled.cancel(false);
			scheduled = null;
		}

		if (soon != null)
		{
			soon.cancel(false);
			soon = null;
		}
	}

	/**
	 * Sends in a few seconds rather than at the next sweep.
	 * <p>
	 * Ignored if one is already on its way, which is what keeps a run of kills to a single request:
	 * the first one books the send and the rest ride along with it.
	 */
	public synchronized void nudge()
	{
		if (soon != null && !soon.isDone())
		{
			return;
		}

		soon = executor.schedule(this::flush, SOON_SECONDS, TimeUnit.SECONDS);
	}

	/**
	 * Throws away anything queued for a challenge that no longer exists.
	 */
	public void forget(String challengeCode)
	{
		outbox.forget(challengeCode);
	}

	/**
	 * Sends what is waiting. Safe to call at any time and safe to call twice — an event the service has
	 * already seen is ignored by it, and only a confirmed send clears anything locally.
	 */
	public void flush()
	{
		try
		{
			if (outbox.isEmpty())
			{
				return;
			}

			boolean sentAnything = false;

			for (Map.Entry<String, List<PendingEvent>> batch : outbox.nextBatch().entrySet())
			{
				String code = batch.getKey();
				String token = challenges.participantTokenFor(code);

				if (token == null)
				{
					// Joined on another account, or left the challenge. There is nobody to report to,
					// and keeping these forever would mean retrying them forever.
					log.debug("Dropping {} events for {}: not a participant", batch.getValue().size(), code);
					outbox.forget(code);
					continue;
				}

				BotwApi.Result<BotwApi.Snapshot> result =
					api.submit(config.serverUrl(), code, token, batch.getValue());

				if (result.isGone())
				{
					// The challenge has been deleted. These events have nowhere to go and never will, so
					// retrying them every minute for as long as the plugin is installed helps nobody.
					// The challenge itself stays on the player's list until they are asked about it.
					log.debug("Dropping {} events for {}: the challenge no longer exists",
						batch.getValue().size(), code);
					outbox.forget(code);
					continue;
				}

				if (!result.ok())
				{
					// Left in place deliberately. The next run tries again, and the ids mean a request
					// that actually landed before timing out will not count twice.
					log.debug("Could not send {} events for {}: {}",
						batch.getValue().size(), code, result.getError());
					continue;
				}

				outbox.confirm(batch.getValue());
				sentAnything = true;
			}

			if (sentAnything)
			{
				onSent.run();
			}
		}
		catch (Exception e)
		{
			// A scheduled task that throws stops being scheduled, which would quietly end all tracking.
			log.warn("Sending failed", e);
		}
	}
}

package com.botw.track;

import com.botw.BotwConfig;
import com.botw.data.BossDrops;
import com.botw.data.Challenge;
import com.botw.data.ChallengeType;
import com.botw.data.DropRule;
import com.botw.data.MinigameTarget;
import com.botw.data.WeeklyRewards;
import com.botw.data.WeeklyTargets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.NPC;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.ChatMessage;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.events.ServerNpcLoot;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.client.util.Text;
import net.runelite.http.api.loottracker.LootRecordType;

/**
 * Watches for kills of whichever boss the joined challenges are about.
 * <p>
 * Two events are listened for because one is not enough. {@link NpcLootReceived} fires when a monster
 * dies and drops something on the floor, which covers every ordinary boss and needs nothing else
 * switched on. The loot tracker's {@link LootReceived} covers the ones that pay out through a chest
 * instead — raids, Tombs of Amascut, the Nightmare — where nothing ever dies at your feet. Listening
 * only to the first would silently ignore a raid; only to the second would require the Loot Tracker
 * plugin to be enabled, and would miss the plain cases if it were not.
 * <p>
 * A pet arrives by neither. The game never drops one — it hands it straight to the player and says so
 * in the chat, so a plugin reading only loot events sees the rarest thing in the game happen and
 * records nothing. That is what {@link #onChatMessage} is for.
 * <p>
 * The two loot events overlap, and that overlap has to be cut out. The Loot Tracker takes every
 * {@link NpcLootReceived} and re-announces it as a {@link LootReceived} of type
 * {@link LootRecordType#NPC}, so an ordinary boss arrives here twice and would be counted twice. See
 * {@link #countsAsKill}.
 * <p>
 * Nothing is scored here. This decides what happened and hands it to the outbox; what it is worth is
 * the service's decision, and deliberately not the client's.
 */
@Slf4j
@Singleton
public class KillTracker
{
	/**
	 * What the game says when a pet drops, in the three places it can put one.
	 * <p>
	 * Followed home, into the last inventory slot, or — the one that started this — into the bank,
	 * when the player already had a pet out and no room to carry another. All three mean the same
	 * thing to a competition: they rolled it and they got it. Where it physically went is between
	 * them and Probita.
	 * <p>
	 * Matched as a fragment of the line rather than the whole of it, because the game punctuates these
	 * differently depending on where the pet went, and the tail of the sentence is not worth being
	 * wrong about. These are the same three the RuneLite screenshot plugin has matched for years.
	 */
	private static final List<String> PET_MESSAGES = Arrays.asList(
		"You have a funny feeling like you're being followed",
		"You feel something weird sneaking into your backpack",
		"You have a funny feeling like you would have been followed");

	/**
	 * How far apart a pet announcement and the kill it came from are allowed to be.
	 * <p>
	 * Needed because the announcement names no boss. Somebody who gets a Beaver while cutting yews on
	 * a Vorkath week has not got Vorki, and without this they would be paid for it.
	 * <p>
	 * Generous, and deliberately counted in both directions: at the raids the pet is announced when the
	 * raid ends but the kill is not recorded until the chest is opened, which is minutes of walking
	 * later at Tombs of Amascut. A minute covers the ordinary case in both orders; anything further out
	 * than that is not the same event.
	 */
	private static final long PET_WINDOW_MS = 60_000;

	private static final List<Integer> SEPULCHRE_REGIONS = Arrays.asList(
		8797, 9051, 9052, 9053, 9054, 9309, 9563, 9565, 9821, 10074, 10075, 10077);

	private enum LootSource { GROUND, EVENT, SERVER }

	private static final String COLLECTION_LOG = "New item added to your collection log: ";
	private static final long NAMED_PET_DEDUP_MS = 6_000;
	private final Map<String, Long> namedPets = new HashMap<>();
	private final Client client;
	private final Outbox outbox;
	private final ChallengeStore challenges;
	private final ItemManager itemManager;
	private final Screenshotter screenshotter;
	private final BossDrops bossDrops;
	private final BotwConfig config;

	/** When each challenge's boss was last killed, so a pet can be tied back to a kill. */
	private final Map<String, Long> lastKillAt = new HashMap<>();

	/** When a pet was last announced, or zero. Kept because the kill can be recorded afterwards. */
	private long petDroppedAt;

	/**
	 * How many pets have been announced this session, which is how one announcement is told from the
	 * next.
	 * <p>
	 * A count rather than the time it happened. Two announcements can share a millisecond, and keying
	 * on the clock quietly made the second of them the first one over again — a player who was owed two
	 * pets was paid for one.
	 */
	private long petAnnouncements;

	/** Which announcement each challenge has already been paid for, so it is not paid twice. */
	private final Map<String, Long> petPaidFor = new HashMap<>();

	@Inject
	private KillTracker(
		Client client,
		Outbox outbox,
		ChallengeStore challenges,
		ItemManager itemManager,
		Screenshotter screenshotter,
		BossDrops bossDrops,
		BotwConfig config)
	{
		this.client = client;
		this.outbox = outbox;
		this.challenges = challenges;
		this.itemManager = itemManager;
		this.screenshotter = screenshotter;
		this.bossDrops = bossDrops;
		this.config = config;
	}

	@Subscribe
	public void onNpcLootReceived(NpcLootReceived event)
	{
		NPC npc = event.getNpc();
		if (npc == null || npc.getName() == null)
		{
			return;
		}

		record(npc.getName(), event.getItems(), 1, LootSource.GROUND);
	}

	@Subscribe
	public void onLootReceived(LootReceived event)
	{
		if (event.getName() == null || !countsAsKill(event.getType()))
		{
			return;
		}

		// A chest can pay out for several kills at once; the amount says how many.
		record(event.getName(), event.getItems(), Math.max(1, event.getAmount()), LootSource.EVENT);
	}

	@Subscribe
	public void onServerNpcLoot(ServerNpcLoot event)
	{
		// The game sends dedicated loot records for these activities, including coffins and
		// Gauntlet chests. Use the original event; ignore the Loot Tracker's NPC echo.
		if (event.getComposition() == null || event.getComposition().getName() == null) return;
		String source = Text.removeTags(event.getComposition().getName());
		if (Arrays.stream(MinigameTarget.values()).anyMatch(target -> target.usesServerLoot() && target.matchesLoot(source)))
		{
			record(source, event.getItems(), 1, LootSource.SERVER);
		}
	}

	static int valeRolls(int offerings)
	{
		return offerings > 0 && offerings % 100 == 0 ? offerings / 100 : 0;
	}

	/**
	 * The pet drops, which arrive as a line of chat and nothing else.
	 * <p>
	 * A pet is never part of the loot. It is handed to the player directly — walking behind them, in
	 * their inventory, or waiting at Probita when they had no room for either — and the only trace of
	 * it is the message. So the two loot listeners above cannot see one, and never could: a clan member
	 * with a full inventory and a pet already out banked theirs and scored nothing, and so would anyone
	 * whose hands were empty.
	 * <p>
	 * The message does not say which pet, so the challenge says it instead; see
	 * {@link BossDrops#petIn}. Nor does it say which boss, which is what the window is for.
	 */
	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM)
		{
			return;
		}

		String message = Text.removeTags(event.getMessage());
		if (message.startsWith(COLLECTION_LOG) && WeeklyTargets.tracksWorld(client))
		{
			recordNamedPet(message.substring(COLLECTION_LOG.length()).trim());
		}
		if (!isPetMessage(message))
		{
			return;
		}

		long now = System.currentTimeMillis();
		petDroppedAt = now;
		petAnnouncements++;

		List<PendingEvent> recorded = new ArrayList<>();

		for (Challenge challenge : challenges.joined())
		{
			Long killed = lastKillAt.get(challenge.getCode());

			// A kill this pet could have come from. Where there is none yet the announcement is kept
			// instead, and the next kill picks it up — the raids announce the pet before they pay out.
			if (challenge.getEventType() == ChallengeType.BOSS && challenge.isRunning(now) && killed != null && fromTheSameKill(now, killed))
			{
				recordPet(challenge, recorded);
			}
		}

		submit(recorded, "a pet");
	}

	/**
	 * Whether a pet announced at one time and a kill recorded at another are the same event.
	 * <p>
	 * Either order counts. The pet normally lands first — it is announced as the boss dies, while the
	 * kill is not recorded until the loot is worked out — but at the raids the gap runs the other way
	 * and is far longer. A zero on either side is nothing having happened, and pairs with nothing.
	 */
	static boolean fromTheSameKill(long petAt, long killAt)
	{
		return petAt > 0 && killAt > 0 && Math.abs(petAt - killAt) <= PET_WINDOW_MS;
	}

	/**
	 * Whether this line of chat is the game announcing a pet.
	 */
	static boolean isPetMessage(String message)
	{
		if (message == null)
		{
			return false;
		}

		for (String pet : PET_MESSAGES)
		{
			if (message.contains(pet))
			{
				return true;
			}
		}

		return false;
	}

	/**
	 * Whether a {@link LootReceived} is a kill in its own right, or one already counted elsewhere.
	 * <p>
	 * Only {@link LootRecordType#EVENT} is. That is the chest payouts — raids, Tombs of Amascut — which
	 * are the reason this event is listened to at all.
	 * <p>
	 * {@link LootRecordType#NPC} is deliberately refused. The Loot Tracker re-announces every
	 * {@link NpcLootReceived} under this event as well, so accepting it would count every ordinary boss
	 * twice over for anyone with that plugin switched on, which is nearly everyone. The first listener
	 * has already had that kill. {@link LootRecordType#PLAYER} and {@link LootRecordType#PICKPOCKET} are
	 * refused because killing someone in the Wilderness or robbing them is not a boss kill.
	 */
	static boolean countsAsKill(LootRecordType type)
	{
		return type == LootRecordType.EVENT;
	}

	/**
	 * @param source the boss's name as the game gave it
	 * @param items  everything that dropped
	 * @param kills  how many kills this payout covers, which is more than one for a chest
	 */
	private void record(String source, Collection<ItemStack> items, int kills, LootSource origin)
	{
		long now = System.currentTimeMillis();
		List<PendingEvent> recorded = new ArrayList<>();

		// One kill can matter to more than one challenge at a time, and the player should not have to
		// choose. Each joined challenge is considered on its own.
		for (Challenge challenge : challenges.joined())
		{
			if (!challenge.isRunning(now)
				|| (challenge.getEventType() != ChallengeType.BOSS && !WeeklyTargets.tracksWorld(client)))
			{
				continue;
			}
			if (origin == LootSource.SERVER && challenge.getEventType() != ChallengeType.MINIGAME) continue;
			int completions;
			boolean petSource = false;
			switch (challenge.getEventType())
			{
				case RAID:
					if (origin != LootSource.EVENT || !WeeklyTargets.raidSource(challenge.getBoss(), source)) continue;
					completions = 0; // Raid KC comes from the completion message, not the chest.
					break;
				case CLUE:
					if (origin != LootSource.EVENT || !source.equalsIgnoreCase("Clue Scroll (" + challenge.getBoss() + ")")) continue;
					completions = kills;
					break;
				case MINIGAME:
					MinigameTarget target = MinigameTarget.forName(challenge.getBoss());
					if (target == null || !target.matchesLoot(source) || origin == LootSource.GROUND
						|| (origin == LootSource.SERVER && !target.usesServerLoot())) continue;
					// Vale is scored by using offerings; all other minigames score on completion.
					completions = target == MinigameTarget.VALE ? valeRolls(kills) : 0;
					break;
				case SKILL:
					completions = 0;
					break;
				default:
					if (!matches(challenge.getBoss(), source)) continue;
					completions = kills;
					petSource = true;
			}
			if (petSource) lastKillAt.put(challenge.getCode(), now);

			for (int remaining = completions; remaining > 0; remaining -= 1000)
			{
				recorded.add(PendingEvent.kills(challenge.getCode(), Math.min(1000, remaining), now));
			}

			if (items != null)
			{
				for (ItemStack stack : items)
				{
					String name = stack == null ? null : scoringItem(challenge, stack);
					if (name != null)
					{
						if (challenge.getEventType() != ChallengeType.BOSS && isNamedPet(challenge, name)
							&& !newPetNotice(challenge, name, now)) continue;
						recorded.add(scoringDrop(challenge, name, stack.getQuantity(), now));
					}
				}
			}

			// A pet announced just before this kill was recorded. That is the ordinary way round at the
			// raids: the pet is announced when the raid ends, the kill when the chest is opened.
			if (petSource && fromTheSameKill(petDroppedAt, now))
			{
				recordPet(challenge, recorded);
			}
		}

		submit(recorded, source);
	}

	/**
	 * Records the pet this challenge counts, if it counts one and has not already been paid for this
	 * announcement.
	 * <p>
	 * The guard is what lets a pet be recorded from either side of the window without being recorded
	 * twice: whichever of the announcement and the kill arrives second finds the challenge already
	 * paid and leaves it alone.
	 * <p>
	 * Nothing here cares whether the player owned that pet already. A duplicate is the same roll of the
	 * same odds, it is announced in the same words, and it scores the same — as a second visage would.
	 */
	private void recordPet(Challenge challenge, List<PendingEvent> into)
	{
		Long paid = petPaidFor.get(challenge.getCode());
		if (paid != null && paid.longValue() == petAnnouncements)
		{
			return;
		}

		String pet = bossDrops.petIn(challenge);
		if (pet == null)
		{
			// A challenge that scores no pet, or lists two and cannot say which. Neither is an error:
			// the creator sets what counts, and a pet they left off is a pet they did not want.
			log.debug("A pet dropped, but {} does not say what it would be worth", challenge.getCode());
			return;
		}

		petPaidFor.put(challenge.getCode(), petAnnouncements);
		into.add(scoringDrop(challenge, pet, 1, petDroppedAt));
	}

	/**
	 * A drop worth points, with the picture that proves it.
	 * <p>
	 * Screenshots are only for drops that actually score. One per kill would bury the ones worth
	 * keeping and fill someone's disk in a week.
	 */
	private void recordNamedPet(String item)
	{
		long now = System.currentTimeMillis();
		List<PendingEvent> recorded = new ArrayList<>();
		for (Challenge challenge : challenges.joined())
		{
			if (challenge.isRunning(now) && challenge.counts(item) && isNamedPet(challenge, item)
				&& petNoticeMatchesActivity(challenge) && newPetNotice(challenge, item, now))
			{
				recorded.add(scoringDrop(challenge, item, 1, now));
			}
		}
		submit(recorded, item);
	}

	private boolean newPetNotice(Challenge challenge, String item, long now)
	{
		namedPets.values().removeIf(last -> now - last > NAMED_PET_DEDUP_MS);
		String key = challenge.getCode() + ":" + item.toLowerCase(Locale.ROOT);
		return namedPets.put(key, now) == null;
	}

	private boolean petNoticeMatchesActivity(Challenge challenge)
	{
		if (challenge.getEventType() != ChallengeType.MINIGAME) return true;
		MinigameTarget target = MinigameTarget.forName(challenge.getBoss());
		if (target == MinigameTarget.GAUNTLET || target == MinigameTarget.CORRUPTED)
		{
			// A bare Youngllef notice does not identify which mode paid out.
			return false;
		}
		if (target == MinigameTarget.SEPULCHRE)
		{
			return client.getLocalPlayer() != null
				&& SEPULCHRE_REGIONS.contains(WorldPoint.fromLocalInstance(client, client.getLocalPlayer().getLocalLocation()).getRegionID());
		}
		return true;
	}

	private boolean isNamedPet(Challenge challenge, String item)
	{
		switch (challenge.getEventType())
		{
			case RAID: return item.equalsIgnoreCase(WeeklyTargets.raidPet(challenge.getBoss()));
			case SKILL: return bossDrops.isPet(item);
			case MINIGAME:
				MinigameTarget target = MinigameTarget.forName(challenge.getBoss());
				return target != null && item.equalsIgnoreCase(target.pet);
			case CLUE: return "Master".equals(challenge.getBoss()) && item.equalsIgnoreCase("Bloodhound");
			default: return false;
		}
	}

	private PendingEvent scoringDrop(Challenge challenge, String itemName, int quantity, long occurredAt)
	{
		// Keyed to the event, so the creator's copy is tied to the drop it is evidence of rather than to
		// a timestamp that has to be matched up by eye.
		PendingEvent drop = PendingEvent.drop(challenge.getCode(), itemName, quantity, occurredAt);

		if (config.screenshotDrops())
		{
			// The code is only passed when sharing is on. Without it the picture is saved locally and
			// goes nowhere, which is what that setting means.
			screenshotter.capture(
				challenge.getName(),
				itemName,
				config.shareScreenshots() ? challenge.getCode() : null,
				config.shareScreenshots() ? drop.getId() : null);
		}

		return drop;
	}

	private void submit(List<PendingEvent> recorded, String source)
	{
		if (!recorded.isEmpty())
		{
			log.debug("Recorded {} events from {}", recorded.size(), source);
			outbox.add(recorded);
		}
	}

	/**
	 * Whether a kill of this thing counts toward a challenge for that boss.
	 * <p>
	 * Not an exact match, because the two names come from different places. A challenge says "Dagannoth
	 * Rex" while the game may hand back a form or a level suffix, and Tombs of Amascut pays out under
	 * the raid's name rather than the boss's.
	 */
	static boolean matches(String boss, String source)
	{
		if (boss == null || source == null)
		{
			return false;
		}

		String wanted = boss.toLowerCase(Locale.ROOT).trim();
		String got = source.toLowerCase(Locale.ROOT).trim();

		return got.equals(wanted) || got.startsWith(wanted + " (") || wanted.startsWith(got + " (");
	}

	/** Resolve a drop back to the name the creator configured, which is also the server's key. */
	private String scoringItem(Challenge challenge, ItemStack stack)
	{
		ItemComposition composition = itemManager.getItemComposition(stack.getId());
		if (composition == null) return null;
		if (challenge.getEventType() == ChallengeType.BOSS)
		{
			String name = composition.getName();
			return name != null && challenge.counts(name) ? name : null;
		}

		String name = composition.getMembersName();
		if (name == null) return null;
		int id = itemManager.canonicalize(stack.getId());
		for (DropRule rule : challenge.getDrops())
		{
			if (!challenge.tracksDrop(rule)) continue;
			int preset = WeeklyRewards.spriteId(rule);
			if (rule.getName().equalsIgnoreCase(name) || (preset > 0 && itemManager.canonicalize(preset) == id)
				|| rewardName(rule.getName()).equals(rewardName(name)))
			{
				return rule.getName();
			}
		}
		return null;
	}

	static String rewardName(String item)
	{
		return item.toLowerCase(Locale.ROOT).replaceFirst(" \\((uncharged|full|empty)\\)$", "");
	}
}

package com.botw.track;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

/**
 * Everything that has happened and has not reached the service yet.
 * <p>
 * Kills are written down first and sent afterwards. That ordering is the whole point: a player is
 * regularly disconnected, offline, or logging out the moment a pet drops, and none of that should
 * cost them the points. An event survives a client restart because it is written to configuration as
 * soon as it is recorded, and leaves only once the service has confirmed it.
 * <p>
 * Every event carries an id made when it happened and never changed, so sending is always safe to
 * retry. The plugin never has to work out whether a request that timed out actually landed — it sends
 * again, and the service ignores what it already has.
 */
@Slf4j
@Singleton
public class Outbox
{
	private static final String CONFIG_GROUP = "botw";
	private static final String KEY = "outbox";

	/**
	 * The service refuses more than fifty at once. Sending in batches also means a long backlog drains
	 * steadily rather than in one request that might time out and achieve nothing.
	 */
	private static final int BATCH = 25;

	/**
	 * A backlog this long means something is badly wrong — the service unreachable for days, most
	 * likely. Older events are dropped rather than growing configuration without limit.
	 */
	private static final int MAX_PENDING = 5000;

	private final ConfigManager configManager;
	private final Gson gson;

	private final List<PendingEvent> pending = new ArrayList<>();

	@Inject
	private Outbox(ConfigManager configManager, Gson gson)
	{
		this.configManager = configManager;
		this.gson = gson;
	}

	public void load()
	{
		pending.clear();

		if (configManager.getRSProfileKey() == null)
		{
			return;
		}

		String json = configManager.getRSProfileConfiguration(CONFIG_GROUP, KEY);
		if (json == null || json.isEmpty())
		{
			return;
		}

		try
		{
			Type type = new TypeToken<List<PendingEvent>>()
			{
			}.getType();

			List<PendingEvent> stored = gson.fromJson(json, type);
			if (stored != null)
			{
				pending.addAll(stored);
			}
		}
		catch (JsonSyntaxException e)
		{
			log.warn("Could not read the pending events", e);
		}

		if (!pending.isEmpty())
		{
			log.debug("{} events still to send", pending.size());
		}
	}

	private void save()
	{
		if (configManager.getRSProfileKey() == null)
		{
			return;
		}

		configManager.setRSProfileConfiguration(CONFIG_GROUP, KEY, gson.toJson(pending));
	}

	/**
	 * Told whenever something is put in, so a kill can be sent shortly afterwards rather than waiting
	 * for the next scheduled sweep. Set by whoever does the sending; does nothing until then.
	 */
	private Runnable onAdded = () ->
	{
	};

	public void setOnAdded(Runnable onAdded)
	{
		this.onAdded = onAdded;
	}

	public void add(Collection<PendingEvent> events)
	{
		synchronized (this)
		{
			pending.addAll(events);

			while (pending.size() > MAX_PENDING)
			{
				pending.remove(0);
			}

			save();
		}

		// Outside the lock. This ends up scheduling work that will come back here for the events, and
		// calling it while holding the monitor is how that turns into a deadlock one day.
		onAdded.run();
	}

	public synchronized boolean isEmpty()
	{
		return pending.isEmpty();
	}

	public synchronized int size()
	{
		return pending.size();
	}

	/**
	 * The next batch to send, grouped by the challenge it belongs to.
	 * <p>
	 * Grouped because the service takes one challenge per request, and a single kill can produce events
	 * for several challenges at once when a player has joined more than one for the same boss.
	 */
	public synchronized Map<String, List<PendingEvent>> nextBatch()
	{
		Map<String, List<PendingEvent>> byChallenge = new LinkedHashMap<>();

		for (PendingEvent event : pending)
		{
			List<PendingEvent> batch =
				byChallenge.computeIfAbsent(event.getChallengeCode(), code -> new ArrayList<>());

			if (batch.size() < BATCH)
			{
				batch.add(event);
			}
		}

		return byChallenge;
	}

	/**
	 * Forgets events the service has confirmed.
	 * <p>
	 * Only called after a successful response. Anything else — a timeout, a refused connection, a
	 * server error — leaves the events exactly where they are, to be tried again.
	 */
	public synchronized void confirm(Collection<PendingEvent> sent)
	{
		List<String> ids = new ArrayList<>();
		for (PendingEvent event : sent)
		{
			ids.add(event.getId());
		}

		pending.removeIf(event -> ids.contains(event.getId()));
		save();
	}

	/**
	 * Drops everything belonging to a challenge, for when it is left or deleted. There is nobody left
	 * to report to.
	 */
	public synchronized void forget(String challengeCode)
	{
		pending.removeIf(event -> event.getChallengeCode().equalsIgnoreCase(challengeCode));
		save();
	}

	public synchronized List<PendingEvent> all()
	{
		return Collections.unmodifiableList(new ArrayList<>(pending));
	}
}

package com.botw.track;

import java.util.UUID;
import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/**
 * Something that happened and has not been told to the service yet.
 * <p>
 * Kills and drops are written down the moment they happen and sent afterwards, rather than sent as
 * they happen. A player killing a boss is regularly offline, mid-disconnect, or logging out the
 * instant a pet drops, and none of that should cost them points.
 * <p>
 * The id is made here and never changes, which is what lets the same event be sent as many times as
 * necessary: the service keys on it and ignores a repeat. Sending is therefore always safe to retry,
 * and the plugin never has to know whether a request that timed out actually landed.
 */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class PendingEvent
{
	/** Which challenge this belongs to. One kill can matter to more than one. */
	private String challengeCode = "";

	private String id = UUID.randomUUID().toString();

	/** {@code kc} or {@code drop}. */
	private String kind = "kc";

	/** Null for a kill. */
	private String itemName;

	/** Kills for a {@code kc} event, quantity for a {@code drop}. */
	private int amount = 1;

	private long occurredAt;

	public static PendingEvent kill(String challengeCode, long occurredAt)
	{
		return kills(challengeCode, 1, occurredAt);
	}

	public static PendingEvent kills(String challengeCode, int amount, long occurredAt)
	{
		return new PendingEvent(
			challengeCode, UUID.randomUUID().toString(), "kc", null, amount, occurredAt);
	}

	public static PendingEvent drop(String challengeCode, String itemName, int quantity, long occurredAt)
	{
		return new PendingEvent(
			challengeCode, UUID.randomUUID().toString(), "drop", itemName, Math.max(1, quantity), occurredAt);
	}
}

package com.botw.track;

import com.botw.BotwFiles;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.IOException;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.Locale;
import javax.imageio.IIOImage;
import javax.imageio.ImageIO;
import javax.imageio.ImageWriteParam;
import javax.imageio.ImageWriter;
import javax.imageio.stream.ImageOutputStream;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.DrawManager;
import net.runelite.client.util.ImageCapture;

/**
 * Saves a picture of the moment a scoring drop landed.
 * <p>
 * A clan that has always verified drops with screenshots will keep wanting them, and asking people to
 * remember to press a key at the exact moment a pet drops is how you end up with no evidence at all.
 * <p>
 * Filed one folder per challenge, because the point is finding them again: "who has proof of that
 * visage on the Vorkath week" should be one folder, not a scroll through a thousand images named after
 * timestamps.
 * <p>
 * The full-size original stays on the player's own machine. Only a smaller copy is sent to the
 * challenge's creator, and only when the player has left that setting on.
 */
@Slf4j
@Singleton
public class Screenshotter
{
	private static final DateTimeFormatter STAMP =
		DateTimeFormatter.ofPattern("yyyy-MM-dd HH-mm-ss", Locale.ENGLISH);

	/** How wide the creator's copy is aimed at. Measured: at 1520 the game's own text reads cleanly. */
	private static final int MAX_WIDTH = 1520;

	/** …but never shrink past this much of the original, however large the client is. */
	private static final double MIN_SCALE = 0.75;

	/** What is polite to send and to keep. The service's own limit is a good deal higher. */
	private static final int BUDGET_BYTES = 300 * 1024;

	private static final float QUALITY = 0.80f;

	/** Used only when the picture is too big at the first quality — a very large client. */
	private static final float LOWER_QUALITY = 0.65f;

	private final DrawManager drawManager;
	private final ImageCapture imageCapture;

	@Inject
	private Screenshotter(DrawManager drawManager, ImageCapture imageCapture)
	{
		this.drawManager = drawManager;
		this.imageCapture = imageCapture;
	}

	/**
	 * Takes a shot of the next frame and files it under this challenge.
	 *
	 * @param challengeName what the creator called it, used as the folder
	 * @param itemName      what dropped, used in the file name so a folder is skimmable
	 */
	public void capture(String challengeName, String itemName)
	{
		capture(challengeName, itemName, null, null);
	}

	/**
	 * @param challengeCode when set, a small copy is also sent to the challenge's creator
	 * @param eventId       ties the picture to the drop it is evidence of
	 */
	public void capture(String challengeName, String itemName, String challengeCode, String eventId)
	{
		// The next frame rather than this one: the drop has only just been announced, and the item is
		// not on screen yet when the event fires.
		drawManager.requestNextFrameListener(image ->
			save(image, challengeName, itemName, challengeCode, eventId));
	}

	private void save(Image image, String challengeName, String itemName,
		String challengeCode, String eventId)
	{
		try
		{
			// With the client frame, so the shot shows the whole window rather than the game viewport
			// alone. That is what makes it read as evidence rather than as a cropped picture.
			BufferedImage shot = imageCapture.addClientFrame(image);

			File folder = BotwFiles.screenshots(safe(challengeName));
			if (!folder.exists() && !folder.mkdirs())
			{
				log.warn("Could not make the screenshot folder {}", folder);
				return;
			}

			String fileName = LocalDateTime.now().format(STAMP) + " " + safe(itemName) + ".png";
			File file = new File(folder, fileName);

			ImageIO.write(shot, "png", file);
			log.debug("Saved {}", file);

			if (challengeCode != null && eventId != null && uploader != null)
			{
				// Best effort, and off this thread. The full-size copy is already on disk, so a failed
				// upload costs the creator a thumbnail rather than the player their evidence.
				uploader.send(challengeCode, eventId, itemName, thumbnail(shot));
			}
		}
		catch (IOException | RuntimeException e)
		{
			// A failed screenshot must never cost anyone their points; the event has already been
			// recorded by the time this runs.
			log.warn("Could not save a screenshot", e);
		}
	}

	/**
	 * The copy that goes to the creator: small enough to store, sharp enough to read.
	 * <p>
	 * It has to be readable, not merely recognisable. What catches a faked drop is usually the game's
	 * own writing — the drop message, or a script's text sitting in the corner where the mouse tooltip
	 * belongs — and that is the first thing to dissolve when a picture is shrunk. An earlier version of
	 * this was six hundred pixels wide and none of that text survived.
	 */
	private static byte[] thumbnail(BufferedImage shot) throws IOException
	{
		return encode(scale(shot, targetWidth(shot.getWidth())), QUALITY, LOWER_QUALITY);
	}

	/** As wide as is worth sending, given how wide the client was. */
	static int targetWidth(int sourceWidth)
	{
		// Two rules, because a single width is wrong at one end or the other. The game draws its text at
		// a fixed pixel size no matter how big the window is, so what decides whether that text survives
		// is how far the picture is shrunk, not what it is shrunk to: a hard 1520 would be generous to a
		// small client and would reduce a 4K one by more than half, which is where the writing goes. So
		// the target is 1520, unless holding to it would mean shrinking past MIN_SCALE — and never more
		// than the client actually gave us.
		return Math.min(sourceWidth, Math.max(MAX_WIDTH, (int) Math.round(sourceWidth * MIN_SCALE)));
	}

	/**
	 * Shrinks by halves rather than in one jump.
	 * <p>
	 * One bilinear step samples four neighbouring pixels, so going straight from 1920 to 600 throws
	 * away most of the picture and turns small writing into grey fuzz. Halving repeatedly means every
	 * pixel of the original contributes to the result.
	 */
	private static BufferedImage scale(BufferedImage source, int width)
	{
		BufferedImage current = source;
		int currentWidth = source.getWidth();
		int currentHeight = source.getHeight();

		while (currentWidth / 2 > width)
		{
			currentWidth /= 2;
			currentHeight = Math.max(1, currentHeight / 2);
			current = draw(current, currentWidth, currentHeight);
		}

		int height = Math.max(1, source.getHeight() * width / Math.max(1, source.getWidth()));
		return draw(current, width, height);
	}

	private static BufferedImage draw(BufferedImage source, int width, int height)
	{
		// INT_RGB rather than ARGB: JPEG has no transparency, and handing an alpha channel to the JPEG
		// writer is what produces those pictures that come back with the colours inverted.
		BufferedImage out = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
		Graphics2D graphics = out.createGraphics();
		graphics.setRenderingHint(
			RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BICUBIC);
		graphics.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
		graphics.drawImage(source, 0, 0, width, height, null);
		graphics.dispose();
		return out;
	}

	/**
	 * JPEG, at the best quality that fits the budget.
	 * <p>
	 * ImageIO's default is around 0.75 and cannot be relied on across machines, so it is set here. The
	 * fallback is for the unusually large client: rather than refuse to send anything, or send
	 * something the service will reject, it drops the quality once and sends that.
	 */
	private static byte[] encode(BufferedImage image, float... qualities) throws IOException
	{
		byte[] encoded = null;

		for (float quality : qualities)
		{
			encoded = write(image, quality);
			if (encoded.length <= BUDGET_BYTES)
			{
				return encoded;
			}
		}

		return encoded;
	}

	private static byte[] write(BufferedImage image, float quality) throws IOException
	{
		ImageWriter writer = ImageIO.getImageWritersByFormatName("jpg").next();
		ImageWriteParam param = writer.getDefaultWriteParam();
		param.setCompressionMode(ImageWriteParam.MODE_EXPLICIT);
		param.setCompressionQuality(quality);

		ByteArrayOutputStream bytes = new ByteArrayOutputStream();

		try (ImageOutputStream stream = ImageIO.createImageOutputStream(bytes))
		{
			writer.setOutput(stream);
			writer.write(null, new IIOImage(image, null, null), param);
		}
		finally
		{
			writer.dispose();
		}

		return bytes.toByteArray();
	}

	/**
	 * Where a thumbnail goes once it has been made. Set by the plugin rather than injected, because the
	 * uploader needs the panel's configuration and this class does not.
	 */
	public interface Uploader
	{
		void send(String challengeCode, String eventId, String itemName, byte[] jpeg);
	}

	private Uploader uploader;

	public void setUploader(Uploader uploader)
	{
		this.uploader = uploader;
	}

	/**
	 * A name that will survive being a folder or a file. Challenge names are typed by people and will
	 * contain colons, slashes and whatever else.
	 */
	private static String safe(String name)
	{
		String cleaned = name == null ? "" : name.replaceAll("[\\\\/:*?\"<>|]", "-").trim();
		return cleaned.isEmpty() ? "Unnamed" : cleaned;
	}
}

package com.botw.track;

import com.botw.data.Challenge;
import com.botw.data.ChallengeType;
import com.botw.data.MinigameTarget;
import com.botw.data.WeeklyTargets;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Experience;
import net.runelite.api.GameState;
import net.runelite.api.Skill;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.util.Text;

@Singleton
public class WeeklyTracker
{
	private static final long XP_BATCH_MS = 60_000;
	private static final Pattern COMPLETION = Pattern.compile(
		"^Your (?:completion count for |subdued |completed )?(.+?) (?:(?:kill|completion) )?(?:count )?is: *([0-9,]+)\\.?$",
		Pattern.CASE_INSENSITIVE);
	private static final Pattern RIFTS = Pattern.compile(
		"^Amount of Rifts you have closed: ([0-9,]+)\\.$", Pattern.CASE_INSENSITIVE);

	private static final Pattern HALLOWED_FLOOR = Pattern.compile(
		"^You have completed Floor ([1-5]) of the Hallowed Sepulchre! Total completions: ([0-9,]+)\\.$");
	private static final int MINE_PAYOUT_TICKS = 4;

	private final Client client;
	private final ChallengeStore challenges;
	private final Outbox outbox;
	private final Map<String, XpBatch> xp = new HashMap<>();
	private final Map<String, Integer> completionTotals = new HashMap<>();
	private final MineRun mine = new MineRun();

	@Inject
	WeeklyTracker(Client client, ChallengeStore challenges, Outbox outbox)
	{
		this.client = client;
		this.challenges = challenges;
		this.outbox = outbox;
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null)
		{
			return;
		}
		if (!WeeklyTargets.tracksWorld(client))
		{
			reset();
			return;
		}
		long now = System.currentTimeMillis();
		List<Challenge> joined = challenges.joined();
		Set<String> running = new HashSet<>();
		Set<String> activeCounters = new HashSet<>();
		List<PendingEvent> recorded = new ArrayList<>();
		boolean mineWon = false;
		if (joined.stream().anyMatch(challenge -> challenge.isRunning(now)
			&& challenge.getEventType() == ChallengeType.MINIGAME && MinigameTarget.MINE.title.equals(challenge.getBoss())))
		{
			Widget hud = client.getWidget(InterfaceID.FossilVolcanicMine.POINTS);
			mineWon = mine.observe(hud != null && !hud.isHidden(), client.getVarbitValue(VarbitID.FOSSIL_MINE_TEMP_PTS),
				client.getSkillExperience(Skill.MINING));
		}
		else
		{
			mine.reset();
		}

		for (Challenge challenge : joined)
		{
			if (!challenge.isRunning(now)) continue;
			if (challenge.getEventType() == ChallengeType.MINIGAME)
			{
				MinigameTarget target = MinigameTarget.forName(challenge.getBoss());
				if (target == MinigameTarget.MINE && mineWon)
				{
					recorded.add(PendingEvent.kill(challenge.getCode(), now));
				}
				if (target != null && target.varp >= 0)
				{
					String code = challenge.getCode();
					int current = client.getVarpValue(target.varp);
					activeCounters.add(code);
					Integer previous = completionTotals.put(code, current);
					// The initial total includes earlier clears. Skip implausible jumps during a sync.
					if (previous != null && previous >= 0 && current > previous && (long) current - previous <= 10)
					{
						for (long total = (long) previous + 1; total <= current; total++)
						{
							recorded.add(count(challenge, "kc", null, Long.toString(total), now));
						}
					}
				}
				continue;
			}
			if (challenge.getEventType() != ChallengeType.SKILL)
			{
				continue;
			}
			Skill skill = WeeklyTargets.skill(challenge.getBoss());
			if (skill == null) continue;
			int current = client.getSkillExperience(skill);
			if (current < 0) continue;
			String code = challenge.getCode();
			running.add(code);
			XpBatch batch = xp.get(code);
			if (batch == null || batch.skill != skill || batch.previous > current
				|| batch.lastObserved < challenge.getStartsAt() || batch.lastObserved > challenge.getEndsAt())
			{
				if (batch != null) batch.drain(code, recorded);
				xp.put(code, new XpBatch(skill, current, now));
				continue;
			}
			batch.lastObserved = now;
			if (current > batch.previous)
			{
				if (batch.gain == 0) batch.firstGain = now;
				batch.gain += current - batch.previous;
				batch.levels += realLevel(current) - realLevel(batch.previous);
				batch.previous = current;
				batch.lastGain = now;
			}
			if (batch.gain > 0 && now - batch.firstGain >= XP_BATCH_MS)
			{
				batch.drain(code, recorded);
			}
		}
		completionTotals.keySet().retainAll(activeCounters);
		Iterator<Map.Entry<String, XpBatch>> entries = xp.entrySet().iterator();
		while (entries.hasNext())
		{
			Map.Entry<String, XpBatch> entry = entries.next();
			if (!running.contains(entry.getKey()))
			{
				entry.getValue().drain(entry.getKey(), recorded);
				entries.remove();
			}
		}
		if (!recorded.isEmpty()) outbox.add(recorded);
	}

	/** Flush XP before a login can replace the account's outbox. */
	public void reset()
	{
		List<PendingEvent> recorded = new ArrayList<>();
		xp.forEach((code, batch) -> batch.drain(code, recorded));
		xp.clear();
		completionTotals.clear();
		mine.reset();
		if (!recorded.isEmpty()) outbox.add(recorded);
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM)
		{
			return;
		}
		String message = Text.removeTags(event.getMessage());
		Matcher raid = completionMessage(event.getMessage());
		Matcher rift = RIFTS.matcher(message);
		boolean completion = raid.matches();
		Matcher hallowed = hallowedFloorMessage(event.getMessage());
		boolean riftClosed = rift.matches();
		boolean floorCleared = hallowed.matches();
		if ((!completion && !riftClosed && !floorCleared) || client.getLocalPlayer() == null || !WeeklyTargets.tracksWorld(client)) return;

		long now = System.currentTimeMillis();
		List<PendingEvent> recorded = new ArrayList<>();
		for (Challenge challenge : challenges.joined())
		{
			if (!challenge.isRunning(now)) continue;
			if (completion && challenge.getEventType() == ChallengeType.RAID)
			{
				String mode = WeeklyTargets.raidMode(challenge.getBoss(), raid.group(1));
				if (mode != null) recorded.add(count(challenge, "raid", mode, raid.group(2), now));
			}
			else if (challenge.getEventType() == ChallengeType.MINIGAME)
			{
				MinigameTarget target = MinigameTarget.forName(challenge.getBoss());
				if (target == MinigameTarget.RIFT && riftClosed)
				{
					recorded.add(count(challenge, "kc", null, rift.group(1), now));
				}
				else if (target == MinigameTarget.SEPULCHRE && floorCleared)
				{
					// Each floor has its own lifetime counter.
					recorded.add(count(challenge, "kc", "floor-" + hallowed.group(1), hallowed.group(2), now));
				}
				else if (target != null && completion && target.matchesCompletion(raid.group(1)))
				{
					// Same key as the native counter, so hearing both can only score once.
					recorded.add(count(challenge, "kc", null, raid.group(2), now));
				}
			}
		}
		if (!recorded.isEmpty()) outbox.add(recorded);
	}

	static Matcher completionMessage(String message)
	{
		return COMPLETION.matcher(Text.removeTags(message));
	}

	static Matcher hallowedFloorMessage(String message)
	{
		return HALLOWED_FLOOR.matcher(Text.removeTags(message));
	}

	static int realLevel(int xp)
	{
		return Math.min(Experience.MAX_REAL_LEVEL, Experience.getLevelForXp(xp));
	}

	/** The lifetime total identifies a single completion, even if its message is repeated. */
	private PendingEvent count(Challenge challenge, String kind, String mode, String lifetime, long now)
	{
		String key = challenge.getCode() + ":" + client.getAccountHash() + ":" + kind + ":" + mode
			+ ":" + lifetime.replace(",", "");
		String id = UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8)).toString();
		return new PendingEvent(challenge.getCode(), id, kind, mode, 1, now);
	}

	/** The exit payout identifies a successful run; disappearing HUD alone can also mean a death. */
	static final class MineRun
	{
		private int points;
		private int xp;
		private int exitTicks;
		private boolean payoutOnLastHudTick;

		boolean observe(boolean hudVisible, int livePoints, int miningXp)
		{
			if (hudVisible)
			{
				// On some transitions XP arrives one tick before the interface closes.
				payoutOnLastHudTick = livePoints == 0 && isPayout(points, miningXp - xp);
				if (livePoints > 0 || !payoutOnLastHudTick) points = livePoints;
				xp = miningXp;
				exitTicks = 0;
				return false;
			}
			if (payoutOnLastHudTick)
			{
				reset();
				return true;
			}
			if (points <= 0 || xp < 0 || ++exitTicks > MINE_PAYOUT_TICKS)
			{
				reset();
				return false;
			}
			if (!isPayout(points, miningXp - xp))
			{
				return false;
			}
			reset();
			return true;
		}

		private static boolean isPayout(int points, int gain)
		{
			return points > 0 && gain >= Math.floor(3.8 * points) && gain <= Math.ceil(3.895 * points);
		}

		void reset()
		{
			points = 0;
			exitTicks = 0;
			payoutOnLastHudTick = false;
		}
	}

	private static final class XpBatch
	{
		private final Skill skill;
		private int previous;
		private int gain;
		private int levels;
		private long lastObserved;
		private long firstGain;
		private long lastGain;

		private XpBatch(Skill skill, int previous, long now)
		{
			this.skill = skill;
			this.previous = previous;
			this.lastObserved = now;
		}

		private void drain(String code, List<PendingEvent> recorded)
		{
			if (gain == 0) return;
			recorded.add(new PendingEvent(code, UUID.randomUUID().toString(), "xp", skill.getName(), gain, lastGain));
			if (levels > 0)
			{
				recorded.add(new PendingEvent(code, UUID.randomUUID().toString(), "level", skill.getName(), levels, lastGain));
			}
			gain = 0;
			levels = 0;
		}
	}
}

